type Entry = {
  term: string;
  expansion?: string;
  category: string;
  domainSlug: string;
  meaning: string;
  example: string;
  boundary?: string;
  aliases?: string[];
  officialUrl?: string;
  lastReviewed: string;
};

function g(term: string, expansion: string | undefined, category: string, domainSlug: string, meaning: string, example: string, boundary?: string, aliases?: string[], officialUrl?: string): Entry {
  return { term, expansion, category, domainSlug, meaning, example, boundary, aliases, officialUrl, lastReviewed: '2026-08-31' };
}

